// The AI proposes; this node decides whether the proposal is even allowed to
// reach a human. Everything here is deterministic.

// ---- GUARD RAILS — this block is the write policy. ----
const MAX_FIELDS = 5;                       // most fields one change may touch
const PROTECTED = ['Id'];                   // columns that may never be edited
// -------------------------------------------------------

const raw = String($json.output ?? $json.text ?? '').trim();

// A plain prose answer is a question, not a change.
const start = raw.indexOf('{'), end = raw.lastIndexOf('}');
let proposal = null;
if (start !== -1 && end > start) {
  const body = raw.slice(start, end + 1).replace(/^```(?:json)?/i, '').replace(/```\s*$/, '');
  try { proposal = JSON.parse(body); } catch (e) { proposal = null; }
}

if (!proposal || proposal.intent !== 'change') {
  return { json: { isChange: false, answer: raw } };
}

const reject = (why) => ({ json: {
  isChange: false,
  answer: `I did not apply that change: ${why}\n\nNothing was written to the sheet.`,
  rejected: true, why,
} });

const id = String(proposal.id ?? '').trim();
if (!id) return reject('the proposal did not name a row id.');

const updates = proposal.updates;
if (!updates || typeof updates !== 'object' || Array.isArray(updates)) {
  return reject('the proposal contained no fields to change.');
}
const fields = Object.keys(updates).filter(k => String(k).trim() !== '');
if (fields.length === 0) return reject('the proposal contained no fields to change.');
if (fields.length > MAX_FIELDS) {
  return reject(`it would change ${fields.length} fields at once (the limit is ${MAX_FIELDS}).`);
}
const hitProtected = fields.filter(f => PROTECTED.some(p => p.toLowerCase() === f.toLowerCase()));
if (hitProtected.length) {
  return reject(`${hitProtected.join(', ')} is a protected column and can never be edited here.`);
}

// Values are stored as strings — a sheet cell is text until a human says
// otherwise, and this keeps a stray object or array out of the write.
const clean = {};
for (const f of fields) {
  const v = updates[f];
  if (v !== null && typeof v === 'object') return reject(`the new value for ${f} was not a simple value.`);
  clean[String(f).trim()] = v === null || v === undefined ? '' : String(v);
}

return { json: {
  isChange: true,
  id,
  updates: clean,
  reason: String(proposal.reason ?? '').trim() || '(no reason given)',
  requestedBy: String($('When You Ask About the Sheet').first().json.sessionId ?? 'chat'),
} };

// Build the before-and-after from the row AS IT IS NOW, not from what the AI
// believed. A proposal written against stale data shows its true current value
// here, which is exactly when a human should be able to say no.
const p = $('Check the Proposed Change Is Safe').first().json;
const row = $json && Object.keys($json).length && $json.Id !== undefined ? $json : null;

if (!row) {
  return { json: { ...p, applicable: false,
    answer: `No row with Id "${p.id}" exists in the sheet, so there is nothing to change.` } };
}

const changes = [];
for (const [field, next] of Object.entries(p.updates)) {
  if (!(field in row)) {
    return { json: { ...p, applicable: false,
      answer: `The sheet has no column called "${field}", so the change was not applied.` } };
  }
  const before = row[field] === null || row[field] === undefined ? '' : String(row[field]);
  if (before === next) continue;               // already that value — not a change
  changes.push({ field, before, after: next });
}

if (changes.length === 0) {
  return { json: { ...p, applicable: false,
    answer: `Row ${p.id} already holds those values — nothing to change.` } };
}

const preview = changes.map(c =>
  `${c.field}: ${c.before === '' ? '(empty)' : c.before} → ${c.after}`).join('\n');

// Only the fields that really differ are carried forward to the write.
const applyFields = {};
for (const c of changes) applyFields[c.field] = c.after;

return { json: { ...p, applicable: true, changes, preview,
  rowNumber: row.row_number ?? '', applyFields } };

// The approval node hands back only {data:{approved}}, so rebuild the exact
// row shape the Sheets update expects: the key column plus the fields that
// really differ — nothing else is written.
const p = $('Build the Before-and-After Preview').first().json;
return { json: { Id: p.id, ...p.applyFields } };

